const [date, setDate] = React.useState<Date | undefined>(new Date());

<Calendar
  mode="single"
  selected={date}
  onSelect={setDate}
  className="rounded-md border"
/>

const [range, setRange] = React.useState<DateRange | undefined>({
  from: new Date(),
  to: addDays(new Date(), 7)
});

<Calendar
  mode="range"
  selected={range}
  onSelect={setRange}
  className="rounded-md border"
/>

const [color, setColor] = React.useState('#9B6DF2');

<ColorPicker
  value={color}
  onChange={setColor}
  mode="inline"
  label="Accent Color"
/>
